from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from digital_trace.reports import document,table
from digital_trace.common import load
from tools.demo_prepare import DIALOGUE

def build():
 d=document('Цифровой след инженера\nРуководство к релизу 2','Версия 2.0.0 · 18 ноября 2026 года. Для инициатора проекта, конкурсной комиссии и сопровождающего преподавателя.')
 d.add_paragraph('Комплект реализует локальный рабочий цикл: исследование студента с ИИ, исполнение программных экспериментов, сохранение исходных свидетельств, смысловой анализ, рассмотрение преподавателем и выпуск отчётов. Студент работает в диалоге, не переносит переписку в Word и не заполняет технические формы.')
 d.add_heading('Что исправлено',1)
 for x in ['Все исполняемые модули находятся в архиве. Убраны ссылки на отсутствующие каталоги этапов и рабочую папку разработчика.','Оценивание по ключевым словам и заранее заданным уровням заменено смысловым ответом модели с цитатами, контраргументами и проверкой ссылок.','Исходные payload хуков сохраняются побайтно в транзакционной базе. Аргументы модели и результаты исполнителя различаются. Повторная доставка отмечается, но не удаляет сообщение.','Учебная модель занятия 8 позволяет сравнивать варианты компоновки, геометрии, теплового режима и шин. Некорректные параметры и конфликт укороченной ванны отмечаются явно.','При апелляции спорный результат исключается из готовой к переносу ведомости. Решение преподавателя сохраняет исходную рекомендацию ИИ и историю.']:
  d.add_paragraph(x,style='List Bullet')
 d.add_heading('Граница готовности',1)
 d.add_paragraph('Это функциональный локальный релиз для контролируемой демонстрации. Программный цикл проверен в Linux. Новая установка в Windows-аккаунте получателя, полный реальный J0 и права двух университетских аккаунтов ещё не проверены. Система не объявляется прошедшей промышленную или педагогическую приёмку.')
 table(d,['Возможность','Состояние'],[['Материалы курса','15 исходных DOCX с хешами; доступны для работы'],['Программные регрессии','42 проверки пройдены; см. qa/unit-tests.txt'],['Исследовательский пример','4 фактически исполненных запуска Python'],['Смысловой разбор','Выполнен на явно вымышленном примере'],['Почта','Заглушка not_sent_stub по согласованному ТЗ']])
 d.add_page_break();d.add_heading('Первый запуск на Windows',1)
 for x in ['Распакуйте архив в новую папку C:\\DigitalTrace_v2_0. Старую DigitalTrace_Test не заменяйте.','Дважды нажмите setup_windows.cmd. Скрипту нужен Python 3.11+ с командой py. Он создаст среду, установит зависимость Word, выполнит тесты и подготовит определения хуков.','Откройте папку проекта в локальном Codex/ChatGPT Desktop. Отправьте приведённый ниже начальный запрос.','Если приложение просит доверие, нажмите значок хуков под полем ввода. Раскройте определения Digital Trace v2, проверьте пути к Python, dt.py и workspace\\captured и разрешите эти определения.']:
  d.add_paragraph(x,style='List Number')
 d.add_paragraph('Начальный запрос',style='Heading 2')
 d.add_paragraph('Прочитай START_HERE.md и AGENTS.md. Подготовь рабочее место комиссии в workspace, только demo, с вымышленными данными. Я хочу пройти исследование студента, затем приёмку преподавателем. Выполняй технические команды сам. Сначала проверь реальный захват исходных сообщений хуками.')
 d.add_paragraph('Разрешение hook и запись события — разные проверки. Помощник должен показать фактический результат doctor и контрольного прогона. Если захват отсутствует, используется docs/HOOK_DIAGNOSTICS.md. Поиск неподтверждённых меню и повторное создание чатов без диагноза не требуется.')
 d.add_heading('Чему научила прежняя неисправность',1)
 d.add_paragraph('В исходном архиве найдено 57 событий с корректной цепочкой. Прежний захват в итоге заработал. Доверие проекта и успешный hooks/list не доказывали запуск. На снимках пользователя доступ к проверке определений находился через значок под композером. Отдельно требовались доверие текущему определению, корректная Windows-команда и актуальный процесс приложения.')
 d.add_paragraph('Новый установщик сохраняет посторонние хуки, делает резервную копию изменяемой конфигурации и не правит внутреннее хранилище доверия. Контрольный маркер не меняется при каждой неудаче. Проверка J0 не создаёт фиктивных событий.')
 d.add_page_break();d.add_heading('Сценарий комиссии',1)
 steps=[('Подготовка','Покажи examples/Example_Student_Session.docx и кратко объясни, как повторить исследование. Используй только вымышленного студента Иванов Демонстрационный, группу DEMO.','ИИ выдаёт Word-пример, не выдавая его за журнал реального пользователя.'),('Исследование','Начинаю индивидуальное исследование занятия 8 в тестовой среде комиссии. Производительность 15 т/сут, ширина здания не более 12 м. Сначала запусти базовую модель и предложи, какие гипотезы стоит проверить.','Исходная реплика записана hook, реальное исполнение имеет код, параметры, stdout и статус.'),('Изменение модели','Сравни два ряда ванн с одним рядом. Затем проверь укороченную ванну 3 м и снижение теплопотерь. Объясни, какие выводы нельзя делать из этой модели.','Несколько программных экспериментов, обсуждение компромисса и ограничений.'),('Завершение','Я закончил. Покажи итог и после моего подтверждения выполни смысловой анализ, выдай оценку и аналитический Word-отчёт.','Рекомендация связана с точными цитатами и исполненными результатами.'),('Апелляция','Не согласен с оценкой критической проверки геометрии. Зарегистрируй моё объяснение для преподавателя.','Апелляция сохранена; перенос строки ведомости заблокирован.'),('Преподаватель','В тестовой роли преподавателя покажи исходные основания, спорный критерий и историю результатов. После моего решения подготовь ведомость и отчёт по студенту.','ИИ предлагает рассмотрение; решение не придумывается за преподавателя.')]
 for title,prompt,expected in steps:
  d.add_heading(title,2);d.add_paragraph(prompt);d.add_paragraph('Ожидается: '+expected)
 d.add_page_break();d.add_heading('Как работает оценивание',1)
 d.add_paragraph('Модель получает исходные реплики, зафиксированные результаты программ и материал занятия. Она оценивает постановку, эксперименты, понимание, критическую проверку, креативность и рефлексию по K1–K6. Программа проверяет допустимость уровней, точность цитат и арифметику балла. Наличие цитаты не является автоматическим доказательством её смысловой релевантности; преподаватель проверяет вывод.')
 d.add_paragraph('Высокий уровень программного исследования требует ссылки на фактическое исполнение. Недостаточность свидетельств обозначается null, а не нулём. Ответ ИИ не принимается за проявление понимания студента. За попытки и расход ресурса штрафов нет. Обоснованная находка ошибки в материале является положительным свидетельством; простое заявление об ошибке баллов не даёт.')
 d.add_paragraph('В демонстрационном примере рекомендация модели составляет 86,3. В имитации апелляции преподаватель устанавливает 88,0, сохраняя первоначальный результат. Эти числа не являются измерением качества оценивания реальных студентов.')
 d.add_heading('Преподавательское рабочее место',1)
 d.add_paragraph('В малом пилоте студент и преподаватель используют отдельные локальные рабочие места. Передаются ZIP-пакеты в разрешённой папке; её может синхронизировать клиент Google Drive. Импорт проверяет файлы и список студентов, не запускает вложенный код и не утверждает студенческую оценку. Преподаватель проводит свежий смысловой разбор в своём контексте.')
 d.add_paragraph('Ведомость выбирает лучший целый действующий подтверждённый результат по каждому занятию. Открытая апелляция блокирует перенос результата этого занятия. Файл ready_for_transfer.csv содержит только разрешённые строки; автоматическая запись в Платонус не выполняется.')
 d.add_heading('Семестр и рекомендации',1)
 d.add_paragraph('Срок — 105 дней от заданного начала семестра. Попытки не ограничиваются. Просрочка не уничтожает работу; итоговый контроль формирует признак необходимости университетского рассмотрения летнего семестра. Автоматическое зачисление и оплата кредитов требуют полномочий университета и не имитируются.')
 d.add_paragraph('Курсовой отчёт собирает подтверждённые работы и рекомендации по развитию навыков. Пока пройдена часть курса, он явно промежуточный. Рекомендации после выпуска опираются на наблюдаемые учебные действия и не объявляют профессиональную пригодность человека.')
 d.add_page_break();d.add_heading('Паспорт проверок и открытые вопросы',1)
 table(d,['Проверка','Результат'],[['Исходный Windows-журнал','57 событий, цепочка без ошибок'],['Сохранность прежних свидетельств','20 из 20 файлов совпали с baseline'],['Ядро и защитные проверки','42 регрессии; повторение из чистой распаковки в qa'],['Word и ведомости','Созданы в примере; оформительская проверка перед выпуском'],['Установка нового релиза в Windows','Не проверена'],['Полный реальный J0','Не закрыт; basic probe не заменяет fork/interrupt/compaction'],['Независимая анализирующая модель','Отдельный независимый контекст не подтверждён'],['Google Drive и SSO','Права разных аккаунтов не проверены'],['Калибровка всех 15 занятий','Материалы есть; реальная педагогическая проверка впереди']])
 d.add_paragraph('Локальный лимит считает запуски экспериментов. Он не управляет токенами и оплатой подписки GPT. Объём и предоставление платформенного доступа организует университет. Исчерпание локального лимита сохраняет данные; дополнительный доступ добавляет оператор.')
 d.add_paragraph('Почта остаётся заглушкой not_sent_stub. Хеши не защищают от владельца компьютера, переписывающего журнал и хеши. Внешний контрольный якорь отсутствует. Локальные роли не являются SSO. SQLite-базы нельзя синхронизировать как общий открытый файл между машинами. Исполнение Python не является отдельной песочницей.')
 d.add_heading('Состав и продолжение',1)
 d.add_paragraph('STATE.md хранит состояние и следующий шаг. docs/COMMANDS.md описывает технические команды. qa содержит фактические логи, MANIFEST.json — хеши файлов поставки. Три навыка входят в один пакет: студент, анализ и преподаватель. Для работы с открытой папкой достаточно AGENTS.md; регистрация плагина у получателя проверяется отдельно.')
 d.add_paragraph('Техническая документация платформы, проверенная 18.11.2026: https://learn.chatgpt.com/docs/hooks и https://learn.chatgpt.com/docs/build-plugins. Локальные хуки нельзя автоматически считать доступными в браузерном ChatGPT. Изменения определений требуют отдельного доверия пользователя.')
 d.save(ROOT/'docs/Release_Guide.docx')

 b=load(ROOT/'examples/submission_bundle.json');d=document('Пример выполнения индивидуального исследования','Практическое занятие 8 · Проектирование цехов цветной металлургии. Вымышленный студент и диалог для комиссии. Четыре расчётных запуска действительно исполнены Python; этот документ не является реальным J0.')
 d.add_heading('Исследовательская задача',1);d.add_paragraph('Обеспечить 15 т меди в сутки при ограничении ширины здания 12 м. Сравнить компоновки, проверить спорное упрощение методички и оценить, достаточно ли изменения массы шин для выбора экономического решения. Студент направляет исследование, а ИИ адаптирует и исполняет код.')
 for i,(u,a) in enumerate(DIALOGUE):
  d.add_heading('Цикл '+str(i+1) if i<4 else 'Итог студента',1);d.add_paragraph('Студент: '+u);d.add_paragraph('Учебный ИИ: '+a)
 d.add_heading('Фактически полученные результаты',1)
 rows=[]
 for i,r in enumerate(b['runs']):
  x=json.loads(r['stdout']);o=x['outputs'];rows.append([i+1,o['n_baths_fact'],o['building_width_fact_m'],o['area_fact_m2'],o['copper_busbar_mass_kg'],'Да' if x['geometry_feasible'] else 'Нет'])
 table(d,['Запуск','Ванны','Ширина м','Площадь м²','Шины кг','Геометрия'],rows)
 d.add_paragraph('В третьем запуске требуемое циркуляционное тепло равно −1750 Вт: нулевой расход подогрева не исключает необходимость охлаждения. Для укороченной ванны программная проверка показывает конфликт с принятой длиной электродного пакета 5,44 м. Это проверка согласованности учебной модели, а не универсальный запрет на ванны другой конструкции.')
 d.add_heading('Переход к рассмотрению',1);d.add_paragraph('После подтверждения завершения сохраняется основание. Модель анализирует исходные реплики и запуски, формирует рекомендацию 86,3 и Word-обоснование. Студент может оспорить вывод. В прилагаемом учебном примере решение преподавателя 88,0 хранится отдельно, а почтовое уведомление имеет статус заглушки.')
 d.add_paragraph('Сопутствующие файлы: Example_Analytical_Report.docx, Example_Submission.dt.zip, gradebook_open_appeal, gradebook_resolved и Example_Course_Report.docx. Последний является промежуточным отчётом по одному занятию из пятнадцати.')
 d.save(ROOT/'examples/Example_Student_Session.docx')
if __name__=='__main__':build()
